// Chinese localization: the built-in Hack and Inter fonts carry no CJK
// glyphs, so a CJK-capable font has to be loaded or the interface shows
// blanks. Priority: user setting -> font shipped beside OptiScaler ->
// common Windows CJK fonts. Hack stays as the last resort (Latin only),
// and stays assigned to gHackFont for the fixed-width live numbers.
const ImWchar* glyphRanges = OptiScalerLocalization::ChineseGlyphRanges();

auto loadCjkFont = [&](ImFont*& target, const ImFontConfig& baseConfig) -> bool
{
    std::vector<std::filesystem::path> fontCandidates;

    if (Config::Instance()->TTFFontPath.has_value())
        fontCandidates.emplace_back(Config::Instance()->TTFFontPath.value());

    auto dllDir = Util::DllPath().parent_path();
    fontCandidates.emplace_back(dllDir / L"font" / L"wqy-microhei.ttc");
    fontCandidates.emplace_back(dllDir / L"wqy-microhei.ttc");
    fontCandidates.emplace_back("font\\wqy-microhei.ttc");
    fontCandidates.emplace_back(L"C:////Windows////Fonts////msyh.ttc");
    fontCandidates.emplace_back(L"C:////Windows////Fonts////msyh.ttf");
    fontCandidates.emplace_back(L"C:////Windows////Fonts////simhei.ttf");
    fontCandidates.emplace_back(L"C:////Windows////Fonts////Deng.ttf");
    fontCandidates.emplace_back(L"C:////Windows////Fonts////simsun.ttc");

    std::error_code fontFsError;

    for (const auto& candidate : fontCandidates)
    {
        if (candidate.empty() || !std::filesystem::exists(candidate, fontFsError) ||
            !std::filesystem::is_regular_file(candidate, fontFsError))
            continue;

        // Read through the wide path so non-ASCII game folders work, then
        // hand the buffer to ImGui (the atlas frees it).
        std::ifstream fontStream(candidate, std::ios::binary | std::ios::ate);
        if (!fontStream)
            continue;

        const auto fontByteCount = static_cast<std::streamsize>(fontStream.tellg());
        if (fontByteCount <= 0)
            continue;

        void* fontData = IM_ALLOC(static_cast<size_t>(fontByteCount));
        fontStream.seekg(0, std::ios::beg);

        if (!fontStream.read(static_cast<char*>(fontData), fontByteCount))
        {
            IM_FREE(fontData);
            continue;
        }

        fontStream.close();

        ImFontConfig cjkFontConfig = baseConfig;
        cjkFontConfig.FontDataOwnedByAtlas = true;

        target = atlas->AddFontFromMemoryTTF(fontData, static_cast<int>(fontByteCount), fontSize,
                                             &cjkFontConfig, glyphRanges);

        if (target != nullptr)
        {
            LOG_INFO("Chinese UI font loaded: {0}", wstring_to_string(candidate.wstring()));
            return true;
        }

        IM_FREE(fontData);
    }

    return false;
};

// The live numbers keep the built-in Hack face (fixed width), which has no
// CJK glyphs -- that is fine, it is only ever used for digits and symbols.
gHackFont = atlas->AddFontFromMemoryCompressedBase85TTF(hack_compressed_compressed_data_base85,
                                                        fontSize, &fontConfig);

if (!loadCjkFont(gClassicFont, fontConfig))
{
    LOG_WARN("No CJK font found, Chinese interface text will not render correctly");

    gClassicFont = atlas->AddFontFromMemoryCompressedBase85TTF(hack_compressed_compressed_data_base85,
                                                               fontSize, &fontConfig, glyphRanges);
}

// Modern style text. The candidate chain is loaded a second time so this face
// renders Chinese too (a shared atlas font cannot have two glyph ranges); it
// falls back to the classic face when no CJK font is available.
if (!loadCjkFont(gInterFont, fontConfig))
    gInterFont = gClassicFont;

io.FontDefault = gClassicFont;
